// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 x) public {
        // Two independent eligible callers (each has zero balance and supports the token).
        // The fuzzed value only chooses the order in which they are driven; the rule
        // (both succeed) must hold for ANY order and ANY input.
        Caller a = new Caller(c);
        Caller b = new Caller(c);

        if (x % 2 == 0) {
            a.go();
            bool ok2;
            try b.go() { ok2 = true; } catch { ok2 = false; }
            assertTrue(ok2, "second caller's airDrop must succeed");
        } else {
            b.go();
            bool ok2;
            try a.go() { ok2 = true; } catch { ok2 = false; }
            assertTrue(ok2, "second caller's airDrop must succeed");
        }
    }
}

contract Caller {
    ModifierEntrancy public c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function go() external {
        c.airDrop();
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
